/* ============ Frank and the pets: fills and parts ============ */
.sn-frank { overflow: visible; }
.sn-f-coat { fill: var(--color-frank); }
.sn-f-dark { fill: var(--frank-dark); }
.sn-f-light { fill: var(--frank-light); }
.sn-f-blue { fill: var(--color-blue); }
.sn-f-yolk { fill: var(--color-yolk); }
.sn-f-pink { fill: var(--color-pink); }
.sn-f-mint { fill: var(--color-mint); }
.sn-f-milk { fill: var(--color-milk); }
.sn-f-ink { fill: var(--color-ink); }
.sn-f-glint { fill: var(--color-milk); }
.sn-f-coat-cat { fill: var(--color-yolk); }
.sn-f-light-cat { fill: var(--color-milk); }
.sn-f-coat-rabbit { fill: var(--color-milk); }
.sn-f-line { stroke: var(--color-ink); stroke-width: 9; stroke-linejoin: round; }
.sn-f-line-thin { stroke: var(--color-ink); stroke-width: 6; stroke-linejoin: round; }
.sn-pet .sn-f-line { stroke-width: 7; }
.sn-f-outline { fill: var(--color-ink); stroke: var(--color-ink); stroke-width: 18; stroke-linejoin: round; }
.sn-f-ground { fill: color-mix(in oklab, var(--color-ink) 22%, transparent); }
.sn-f-fur, .sn-f-mouth, .sn-f-brow, .sn-f-toes, .sn-f-ring, .sn-f-shell { fill: none; stroke: var(--color-ink); stroke-width: 8; stroke-linecap: round; stroke-linejoin: round; }
.sn-pet .sn-f-mouth, .sn-f-shell { stroke-width: 6; }
.sn-f-blush { fill: var(--color-pink); opacity: 0.55; }
.sn-f-heart-shape { fill: var(--color-pink); stroke: var(--color-ink); stroke-width: 2.5; }
.sn-f-heart-ring { fill: none; stroke: var(--color-pink); stroke-width: 6; }

.sn-frank g, .sn-pet g, .sn-pet path { transform-box: view-box; }
.sn-f-tail { transform-origin: 2090px 330px; }
.sn-f-ear { transform-origin: 350px 116px; }
.sn-f-eye { transform-origin: 236px 198px; }
.sn-f-nose { transform-origin: 92px 266px; }
.sn-f-tag { transform-origin: 462px 404px; }
.sn-f-belly { transform-origin: 1240px 456px; }
.sn-f-paw { transform-origin: 1883px 410px; transition: transform var(--dur-slow) var(--ease-wag); }
.sn-f-heart { transform-origin: 600px 340px; opacity: 0; transform: scale(0.3); transition: opacity var(--dur-base) var(--ease-out), transform var(--dur-base) var(--ease-wag); }
.sn-f-tongue { transform-origin: 180px 320px; transform: scaleY(0); transition: transform var(--dur-base) var(--ease-wag); }

.sn-pet { display: block; width: 100%; height: auto; overflow: visible; }
.sn-pet-head { transform-origin: 200px 200px; }
.sn-pet-blink { transform-origin: 200px 150px; }
.sn-pet-sway { transform-origin: 280px 320px; }
.sn-pet-dog .sn-frank { width: 100%; height: auto; display: block; }

/* ============ the check-up ============ */
.sn-checkup { position: relative; z-index: 2; margin-top: -28px; background: var(--color-blue); color: var(--color-milk); border-radius: var(--r-lg) var(--r-lg) 0 0; border-top: var(--sn-border) solid var(--color-ink); }
.sn-ck-stage { position: relative; display: grid; gap: 40px; max-width: var(--sn-max); margin: 0 auto; padding: 112px var(--sn-gutter) 96px; }
.sn-ck-blobs { position: absolute; inset: 0; overflow: hidden; pointer-events: none; }
.sn-ck-blobs span { position: absolute; border-radius: 50%; background: color-mix(in oklab, var(--color-milk) 9%, transparent); }
.sn-ck-blobs span:first-child { width: 46vmax; aspect-ratio: 1; left: -14vmax; top: -18vmax; }
.sn-ck-blobs span:last-child { width: 30vmax; aspect-ratio: 1; right: -8vmax; bottom: -10vmax; background: color-mix(in oklab, var(--color-yolk) 16%, transparent); }
.sn-ck-head { position: relative; z-index: 2; }
.sn-ck-eyebrow { gap: 14px; }
.sn-ck-count { display: none; padding: 2px 10px; border-radius: 999px; background: var(--color-yolk); color: var(--color-ink); font-variant-numeric: tabular-nums; }
.sn-ck-title { max-width: 14ch; }
.sn-ck-railwrap { position: relative; margin-top: 24px; max-width: 620px; }
.sn-ck-rail { display: flex; flex-wrap: wrap; gap: 8px; }
.sn-ck-rail a { display: block; padding: 8px 14px; border-radius: 999px; border: 2px solid var(--color-milk); text-decoration: none; font-weight: 700; font-size: 0.92rem; transition: color var(--dur-fast) var(--ease-out), transform var(--dur-fast) var(--ease-out); }
.sn-ck-rail a:active { transform: scale(0.95); }
.sn-ck-rail-short { display: none; text-transform: capitalize; }
.sn-ck-rail-pill { display: none; }
.sn-ck-cards { position: relative; z-index: 2; display: grid; grid-template-columns: repeat(auto-fill, minmax(min(300px, 100%), 1fr)); gap: 18px; }
.sn-ck-card { padding: 24px 24px 26px; background: var(--color-milk); color: var(--color-ink); border: var(--sn-border) solid var(--color-ink); border-radius: var(--r); box-shadow: 0 6px 0 var(--color-ink); scroll-margin-top: 110px; }
.sn-ck-card-n { display: inline-block; margin-bottom: 10px; padding: 2px 10px; border-radius: 999px; background: var(--color-yolk); font-weight: 700; }
.sn-ck-card-body { margin-top: 10px; color: var(--ink-soft); }
.sn-ck-services { display: grid; gap: 6px; margin-top: 14px; font-weight: 600; font-size: 0.95rem; }
.sn-ck-services li { display: flex; align-items: center; gap: 8px; }
.sn-ck-frame { position: relative; z-index: 1; }
.sn-ck-track { width: 100%; }
.sn-ck-frank { position: relative; }
.sn-ck-frank .sn-frank { display: block; width: 100%; height: auto; }
.sn-ck-marker { position: absolute; display: grid; place-items: center; width: clamp(26px, 3vw, 40px); aspect-ratio: 1; translate: -50% -50%; border-radius: 50%; background: var(--color-yolk); color: var(--color-ink); border: var(--sn-border) solid var(--color-ink); font-family: var(--font-chart); font-weight: 700; font-size: 0.85rem; }
.sn-ck-ecg { display: block; width: 100%; height: auto; aspect-ratio: 2600 / 100; overflow: visible; }
.sn-ck-ecg path { fill: none; stroke-linecap: round; stroke-linejoin: round; vector-effect: non-scaling-stroke; }
.sn-ck-ecg-ghost { stroke: color-mix(in oklab, var(--color-milk) 30%, transparent); stroke-width: 2; }
.sn-ck-ecg-live { stroke: var(--color-yolk); stroke-width: 4; }
.sn-ck-piece, .sn-ck-stamp, .sn-ck-readout { display: none; }

/* the scrub layout: only with motion welcome and JavaScript running */
@media (prefers-reduced-motion: no-preference) and (scripting: enabled) {
  .sn-checkup { height: 620vh; }
  .sn-ck-stage { position: sticky; top: 0; display: block; height: 100svh; max-width: none; padding: 0; overflow: hidden; --frank-h: clamp(200px, 40svh, 420px); }
  .sn-ck-head { position: absolute; top: calc(92px + 3svh); left: var(--sn-gutter); width: min(560px, 48vw); }
  .sn-ck-title { font-size: clamp(2rem, 1.2rem + 2.8vw, 3.8rem); }
  .sn-ck-railwrap { display: block; }
  .sn-ck-count { display: inline-block; }
  .sn-ck-rail { display: grid; grid-template-columns: repeat(var(--n), minmax(0, 1fr)); gap: 0; padding: 4px; border-radius: 999px; border: 2px solid var(--color-milk); }
  .sn-ck-railwrap { width: 100%; }
  .sn-ck-rail-pill { display: block; position: absolute; top: 4px; bottom: 4px; left: 4px; width: calc((100% - 8px) / var(--n)); border-radius: 999px; background: var(--color-yolk); transform: translateX(calc(var(--rail-i, 0) * 100%)); transition: transform var(--dur-base) var(--ease-spring); }
  .sn-ck-rail a { position: relative; z-index: 1; padding: 7px 4px; border: 0; text-align: center; font-size: 0.82rem; white-space: nowrap; }
  .sn-ck-rail a[aria-current] { color: var(--color-ink); }
  @media (hover: hover) and (pointer: fine) { .sn-ck-rail a:not([aria-current]):hover { color: var(--color-yolk); } }

  .sn-ck-cards { position: absolute; top: calc(92px + 3svh); right: var(--sn-gutter); width: min(400px, 38vw); display: grid; grid-template-columns: none; gap: 0; }
  .sn-ck-card { grid-area: 1 / 1; transition: transform var(--dur-slow) var(--ease-wag), opacity var(--dur-base) var(--ease-out), visibility 0s; }
  .sn-ck-card[data-state="before"] { opacity: 0; transform: translateX(-40px) rotate(-4deg) scale(0.94); visibility: hidden; transition: transform var(--dur-base) var(--ease-out), opacity var(--dur-fast) var(--ease-out), visibility 0s var(--dur-base); }
  .sn-ck-card[data-state="after"] { opacity: 0; transform: translateY(40px) rotate(4deg) scale(0.94); visibility: hidden; transition: transform var(--dur-base) var(--ease-out), opacity var(--dur-fast) var(--ease-out), visibility 0s var(--dur-base); }
  .sn-ck-card[data-state="active"] .sn-ck-services li { animation: sn-chip-in 600ms var(--ease-wag) both; animation-delay: calc(200ms + var(--n, 0) * 70ms); }
  .sn-ck-services li:nth-child(2) { --n: 1; }
  .sn-ck-services li:nth-child(3) { --n: 2; }

  .sn-ck-frame { position: absolute; left: 0; right: 0; bottom: 4svh; height: calc(var(--frank-h) * 1.16); }
  .sn-ck-track { position: absolute; top: 0; left: 0; width: calc(var(--frank-h) * 2600 / 640); transform: translate3d(0, 0, 0); will-change: transform; }
  .sn-ck-frank .sn-frank { height: var(--frank-h); width: 100%; }
  .sn-ck-marker { display: none; }
  .sn-ck-ecg-live { clip-path: inset(0 100% 0 0); }

  .sn-ck-piece { display: block; position: absolute; top: 0; left: var(--anchor, 42%); z-index: 3; width: clamp(54px, 5vw, 76px); aspect-ratio: 1; transform: translate3d(-50%, -50%, 0); }
  .sn-ck-tube { position: absolute; left: 50%; bottom: 50%; width: 90px; height: 130svh; translate: -46% 0; overflow: visible; }
  .sn-ck-tube path { fill: none; stroke: var(--color-ink); stroke-width: 18; stroke-linecap: round; vector-effect: non-scaling-stroke; }
  .sn-ck-tube .sn-ck-tube-shine { stroke: var(--color-pink); stroke-width: 8; }
  .sn-ck-disc { position: absolute; inset: 0; border-radius: 50%; background: radial-gradient(circle at 35% 30%, var(--color-milk) 0 22%, color-mix(in oklab, var(--color-milk) 70%, var(--color-blue)) 60%); border: 5px solid var(--color-ink); box-shadow: 0 5px 0 var(--color-ink); }
  .sn-ck-disc::after { content: ""; position: absolute; inset: 24%; border-radius: 50%; border: 4px solid var(--color-ink); background: var(--color-pink); }
  .sn-ck-pulse { position: absolute; inset: -6px; border-radius: 50%; border: 4px solid var(--color-yolk); animation: sn-pulse 1.4s var(--ease-out) infinite; }

  .sn-ck-readout { display: inline-flex; position: absolute; left: var(--sn-gutter); bottom: calc(4svh + var(--frank-h) * 1.16 + 10px); z-index: 2; align-items: center; gap: 10px; padding: 6px 14px; border-radius: 999px; background: var(--color-ink); color: var(--color-paper); font-weight: 700; }
  .sn-ck-dot { width: 10px; height: 10px; border-radius: 50%; background: var(--color-mint); animation: sn-beat 0.66s ease-in-out infinite; }

  .sn-ck-stamp { display: block; position: absolute; left: calc(var(--anchor, 42%) + 7vw); bottom: calc(4svh + var(--frank-h) * 0.62); z-index: 4; width: clamp(130px, 14vw, 200px); color: var(--color-mint); opacity: 0; transform: scale(2.2) rotate(-30deg); transition: opacity var(--dur-fast) var(--ease-out), transform var(--dur-slow) var(--ease-wag); pointer-events: none; }
  .sn-ck-stage[data-done="true"] .sn-ck-stamp { opacity: 1; transform: scale(1) rotate(-12deg); }

  /* Frank reacts to the part under the stethoscope */
  [data-chapter="nose"] .sn-f-nose { animation: sn-sniff 1.1s ease-in-out infinite; }
  [data-chapter="ears"] .sn-f-ear { animation: sn-flop 1.5s var(--ease-wag) infinite; }
  [data-chapter="heart"] .sn-f-heart { opacity: 1; transform: none; }
  [data-chapter="heart"] .sn-f-heart-shape { transform-box: fill-box; transform-origin: center; animation: sn-beat 0.66s ease-in-out infinite; }
  [data-chapter="belly"] .sn-f-belly { animation: sn-breathe 2.2s ease-in-out infinite; }
  [data-chapter="paws"] .sn-f-paw { transform: rotate(-16deg) translateY(-18px); }
  [data-chapter="tail"] .sn-f-tail { animation: sn-wag 0.42s ease-in-out infinite alternate; }
  [data-done="true"] .sn-f-tail { animation-duration: 0.24s; }
  [data-done="true"] .sn-f-tongue, [data-chapter="tail"] .sn-f-tongue { transform: none; }
}

@media (prefers-reduced-motion: no-preference) and (scripting: enabled) and (max-width: 760px) {
  .sn-checkup { height: 560vh; }
  .sn-ck-stage { --frank-h: clamp(170px, 30svh, 260px); }
  .sn-ck-head { top: calc(84px + 1svh); width: auto; right: var(--sn-gutter); }
  .sn-ck-title { font-size: clamp(1.7rem, 7.4vw, 2.3rem); }
  .sn-ck-rail-long { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  .sn-ck-rail-short { display: inline; }
  .sn-ck-rail a { font-size: 0.76rem; }
  .sn-ck-cards { top: auto; bottom: calc(4svh + var(--frank-h) * 1.16 + 56px); left: var(--sn-gutter); right: var(--sn-gutter); width: auto; }
  .sn-ck-card { padding: 16px 18px 18px; }
  .sn-ck-card-body { display: none; }
  .sn-ck-services { margin-top: 8px; font-size: 0.86rem; }
  .sn-ck-readout { bottom: calc(4svh + var(--frank-h) * 1.16 + 8px); font-size: 0.75rem; }
  .sn-ck-stamp { left: auto; right: var(--sn-gutter); bottom: calc(4svh + var(--frank-h) * 0.9); width: 104px; }
}
@media (prefers-reduced-motion: no-preference) and (scripting: enabled) and (max-height: 700px) and (min-width: 761px) {
  .sn-ck-card-body { display: none; }
  .sn-ck-stage { --frank-h: clamp(160px, 34svh, 300px); }
}

@keyframes sn-sniff { 0%, 100% { transform: none; } 20% { transform: scale(1.12, 0.9); } 32% { transform: none; } 44% { transform: scale(1.1, 0.92); } }
@keyframes sn-flop { 0%, 100% { transform: rotate(0deg); } 30% { transform: rotate(16deg); } 60% { transform: rotate(-5deg); } }
@keyframes sn-beat { 0%, 100% { transform: scale(1); } 18% { transform: scale(1.22); } 36% { transform: scale(0.96); } 52% { transform: scale(1.1); } }
@keyframes sn-breathe { 0%, 100% { transform: scaleY(1); } 50% { transform: scaleY(1.45) translateY(-3px); } }
@keyframes sn-wag { from { transform: rotate(-14deg); } to { transform: rotate(16deg); } }
@keyframes sn-pulse { from { transform: scale(0.9); opacity: 1; } to { transform: scale(1.6); opacity: 0; } }
@keyframes sn-chip-in { from { opacity: 0; transform: translateY(12px) scale(0.9); } }

/* ============ shared section shell ============ */
.sn-sec { position: relative; z-index: 3; padding: clamp(84px, 11vw, 150px) var(--sn-gutter); border-radius: var(--r-lg) var(--r-lg) 0 0; margin-top: -40px; border-top: var(--sn-border) solid var(--color-ink); }
.sn-sec > * { max-width: var(--sn-max); margin-inline: auto; }
.sn-sec-head { margin-bottom: clamp(36px, 5vw, 64px); }

/* ============ who we see ============ */
.sn-patients { background: var(--color-paper); }
.sn-tabs { position: relative; display: grid; grid-template-columns: repeat(var(--n), minmax(0, 1fr)); max-width: 640px; padding: 5px; border-radius: 999px; background: var(--color-milk); border: var(--sn-border) solid var(--color-ink); box-shadow: 0 5px 0 var(--color-ink); }
.sn-tabs-pill { position: absolute; top: 5px; bottom: 5px; left: 5px; width: calc((100% - 10px) / var(--n)); border-radius: 999px; background: var(--color-pink); border: 2px solid var(--color-ink); transform: translateX(calc(var(--active) * 100%)); transition: transform var(--dur-base) var(--ease-spring); }
.sn-tabs button { position: relative; z-index: 1; padding: 11px 6px; border: 0; background: none; border-radius: 999px; font-weight: 700; cursor: pointer; transition: transform var(--dur-fast) var(--ease-out); }
.sn-tabs button:active { transform: scale(0.94); }
.sn-species-panels { display: grid; margin-top: 40px; --px: 0; --py: 0; }
.sn-species-panel { grid-area: 1 / 1; display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: clamp(24px, 5vw, 80px); align-items: center; }
.sn-species-art { position: relative; aspect-ratio: 1; max-width: 520px; width: 100%; }
.sn-layer { position: absolute; transition: transform 700ms var(--ease-out); }
.sn-layer-blob { inset: 6%; border: var(--sn-border) solid var(--color-ink); border-radius: 46% 54% 58% 42% / 52% 44% 56% 48%; transform: translate(calc(var(--px) * -14px), calc(var(--py) * -14px)); }
[data-species="dog"] .sn-layer-blob { background: var(--color-yolk); }
[data-species="cat"] .sn-layer-blob { background: var(--color-pink); }
[data-species="rabbit"] .sn-layer-blob { background: var(--color-mint); }
[data-species="small"] .sn-layer-blob { background: var(--color-blue); }
.sn-layer-pet { left: 8%; top: 8%; width: 70%; transform: translate(calc(var(--px) * 22px), calc(var(--py) * 18px)); }
.sn-layer-photo { right: 0; bottom: 0; width: 46%; transform: translate(calc(var(--px) * 40px), calc(var(--py) * 30px)) rotate(6deg); }
.sn-polaroid { padding: 8px 8px 10px; background: var(--color-milk); border: var(--sn-border) solid var(--color-ink); border-radius: 12px; box-shadow: 0 5px 0 var(--color-ink); }
.sn-polaroid > :first-child { display: block; aspect-ratio: 1; overflow: hidden; border-radius: 6px; }
.sn-polaroid img { width: 100%; height: 100%; object-fit: cover; }
.sn-polaroid figcaption { margin-top: 6px; font-size: 0.66rem; line-height: 1.3; }
.sn-species-copy { display: grid; gap: 16px; }
.sn-species-copy > p:first-of-type { color: var(--ink-soft); }
.sn-species-count { display: flex; align-items: baseline; gap: 10px; }
.sn-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.sn-chips li { display: inline-flex; align-items: center; gap: 6px; padding: 7px 14px; border-radius: 999px; background: var(--color-milk); border: 2px solid var(--color-ink); font-weight: 600; font-size: 0.92rem; }
@media (prefers-reduced-motion: no-preference) {
  .sn-species-panel { transition: opacity var(--dur-base) var(--ease-out), transform var(--dur-slow) var(--ease-wag), visibility 0s; }
  .sn-species-panel[data-state="before"] { opacity: 0; transform: translateX(-70px) rotate(-2deg); visibility: hidden; transition: opacity var(--dur-fast) var(--ease-out), transform var(--dur-base) var(--ease-out), visibility 0s var(--dur-base); }
  .sn-species-panel[data-state="after"] { opacity: 0; transform: translateX(70px) rotate(2deg); visibility: hidden; transition: opacity var(--dur-fast) var(--ease-out), transform var(--dur-base) var(--ease-out), visibility 0s var(--dur-base); }
  .sn-species-panel[data-state="active"] .sn-chips li { animation: sn-chip-in 600ms var(--ease-wag) both; animation-delay: calc(240ms + var(--i) * 70ms); }
  .sn-species-panel[data-state="active"] .sn-layer-pet .sn-pet { animation: sn-pop-in 800ms var(--ease-wag) both 120ms; }
  .sn-species-panel[data-state="active"] .sn-pet-sway { animation: sn-sway 2.8s ease-in-out infinite alternate; }
  .sn-species-panel[data-state="active"] .sn-pet-blink { animation: sn-blink 4.6s ease-in-out 1s infinite; }
}
@media (prefers-reduced-motion: reduce) {
  .sn-species-panel:not([data-state="active"]) { visibility: hidden; }
}

/* ============ plans ============ */
.sn-plans { background: var(--color-pink); }
.sn-plans-controls { display: flex; flex-wrap: wrap; gap: 16px; align-items: center; margin-bottom: 52px; }
.sn-switch { position: relative; display: grid; grid-template-columns: 1fr 1fr; padding: 5px; border-radius: 999px; background: var(--color-milk); border: var(--sn-border) solid var(--color-ink); }
.sn-switch-knob { position: absolute; top: 5px; bottom: 5px; left: 5px; width: calc(50% - 5px); border-radius: 999px; background: var(--color-ink); transition: transform var(--dur-base) var(--ease-spring); }
.sn-switch[data-billing="yearly"] .sn-switch-knob { transform: translateX(100%); }
.sn-switch button { position: relative; z-index: 1; padding: 10px 18px; border: 0; background: none; border-radius: 999px; font-weight: 700; cursor: pointer; white-space: nowrap; transition: color var(--dur-fast) var(--ease-out); }
.sn-switch button[aria-checked="true"] { color: var(--color-paper); }
.sn-stepper { display: inline-flex; align-items: center; gap: 4px; padding: 5px; border-radius: 999px; background: var(--color-milk); border: var(--sn-border) solid var(--color-ink); }
.sn-stepper button { width: 42px; height: 42px; border-radius: 50%; border: 2px solid var(--color-ink); background: var(--color-yolk); font-size: 1.3rem; font-weight: 800; line-height: 1; cursor: pointer; transition: transform var(--dur-base) var(--ease-spring); }
.sn-stepper button:active:not(:disabled) { transform: scale(0.88); transition-duration: var(--dur-instant); }
.sn-stepper button:disabled { opacity: 0.45; cursor: not-allowed; }
.sn-stepper output { min-width: 84px; text-align: center; font-weight: 700; }
.sn-roll { display: inline-block; }
.sn-tags { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: clamp(16px, 2.6vw, 36px); align-items: start; }
.sn-tag-hang { position: relative; padding-top: 30px; transform-origin: 50% 0; perspective: 1200px; }
.sn-tag-hang[data-plan="grown"] { margin-top: -18px; }
.sn-tag-ring { position: absolute; top: 0; left: 50%; width: 46px; height: 46px; translate: -50% 0; border-radius: 50%; border: 6px solid var(--color-ink); background: transparent; }
.sn-tag { position: relative; display: grid; transform-style: preserve-3d; transition: transform 800ms var(--ease-spring); }
.sn-tag[data-flipped="true"] { transform: rotateY(180deg); }
.sn-tag-face {
  grid-area: 1 / 1; display: flex; flex-direction: column; gap: 10px; padding: 52px 26px 26px; min-height: 100%;
