/* ============ after hours ============ */
.sn-after { position: relative; z-index: 4; margin-top: -40px; padding: clamp(80px, 10vw, 130px) var(--sn-gutter); background: var(--color-ink); color: var(--color-paper); border-radius: var(--r-lg) var(--r-lg) 0 0; }
