/* ============ book ============ */
.sn-book { position: relative; z-index: 5; margin-top: -40px; padding: clamp(84px, 10vw, 140px) var(--sn-gutter); background: var(--color-blue); color: var(--color-milk); border-radius: var(--r-lg) var(--r-lg) 0 0; border-top: var(--sn-border) solid var(--color-ink); }
.sn-book-inner { max-width: var(--sn-max); margin: 0 auto; display: grid; grid-template-columns: 0.9fr 1.1fr; gap: clamp(32px, 5vw, 80px); align-items: start; }
.sn-book .sn-sec-lede { color: color-mix(in oklab, var(--color-milk) 88%, var(--color-blue)); }
.sn-book-ball { margin-top: 24px; max-width: 360px; }
.sn-book-card { padding: clamp(22px, 3vw, 40px); background: var(--color-milk); color: var(--color-ink); border: 4px solid var(--color-ink); border-radius: var(--r-lg); box-shadow: 0 8px 0 var(--color-ink); }

.sn-booking { display: grid; }
.sn-form, .sn-done { grid-area: 1 / 1; }
.sn-form { display: grid; gap: 18px; transition: opacity var(--dur-base) var(--ease-out), transform var(--dur-slow) var(--ease-in-out), visibility 0s; }
.sn-booking[data-phase="done"] .sn-form { opacity: 0; transform: translateY(30px) scale(0.96); visibility: hidden; transition: opacity var(--dur-base) var(--ease-out), transform var(--dur-slow) var(--ease-in-out), visibility 0s var(--dur-slow); }
