  width: 100%; padding: 22px 46px 10px 18px; border: var(--sn-border) solid var(--color-ink); border-radius: 16px; background: var(--color-paper);
  font: inherit; color: var(--color-ink); outline: 3px solid transparent; outline-offset: 0; transition: outline-offset var(--dur-fast) var(--ease-out), outline-color var(--dur-fast) var(--ease-out), background-color var(--dur-fast) var(--ease-out);
