.sn-chip > span { display: inline-flex; align-items: center; gap: 6px; padding: 9px 16px; border-radius: 999px; border: var(--sn-border) solid var(--color-ink); background: var(--color-paper); font-weight: 700; transition: transform var(--dur-base) var(--ease-spring), background-color var(--dur-fast) var(--ease-out); }
