@media (hover: hover) and (pointer: fine) { .sn-chip:hover input:not(:checked) + span { background: var(--color-milk); transform: translateY(-2px); } }
.sn-days { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); }
