.sn-field-error { display: grid; grid-template-rows: 0fr; margin-top: 0; color: var(--color-ink); font-weight: 700; font-size: 0.88rem; transition: grid-template-rows var(--dur-base) var(--ease-out), margin var(--dur-base) var(--ease-out); }
