.sn-submit-dots { position: absolute; right: 26px; top: calc(50% - 3px); display: flex; gap: 5px; translate: 0 -50%; opacity: 0; transition: opacity var(--dur-fast) var(--ease-out); }
.sn-submit-dots i { width: 8px; height: 8px; border-radius: 50%; background: var(--color-ink); }
