@keyframes sn-dot { 50% { transform: translateY(-6px); } }
@keyframes sn-tag-in { 0% { opacity: 0; transform: translateY(-80px) rotate(-14deg); } 30% { opacity: 1; } 100% { transform: none; } }
@keyframes sn-stamp { from { opacity: 0; transform: scale(2.4) rotate(-40deg); } to { opacity: 1; transform: rotate(-14deg); } }

/* the ball */
