}
@keyframes sn-ball-bob { 50% { transform: translateY(-10px); } }
@keyframes sn-throw-a { 0% { transform: none; } 28% { transform: translate(40%, -160%) scale(0.2) rotate(400deg); opacity: 0.9; } 30%, 52% { opacity: 0; transform: translate(220%, 0); } 54% { opacity: 1; } 70% { transform: translate(60%, 0) rotate(-200deg); } 80% { transform: translate(28%, -30%) rotate(-280deg); } 90% { transform: translate(8%, 0) rotate(-330deg); } 100% { transform: none; } }
@keyframes sn-throw-b { 0% { transform: none; } 28% { transform: translate(40%, -160%) scale(0.2) rotate(400deg); opacity: 0.9; } 30%, 52% { opacity: 0; transform: translate(220%, 0); } 54% { opacity: 1; } 70% { transform: translate(60%, 0) rotate(-200deg); } 80% { transform: translate(28%, -30%) rotate(-280deg); } 90% { transform: translate(8%, 0) rotate(-330deg); } 100% { transform: none; } }

/* ============ footer ============ */
.sn-footer { position: relative; z-index: 6; margin-top: -40px; padding: clamp(72px, 9vw, 110px) var(--sn-gutter) 90px; background: var(--color-ink); color: var(--color-paper); border-radius: var(--r-lg) var(--r-lg) 0 0; overflow: hidden; }
